    // @formatter:on

    private fun modulePredicate(): TraceabilityPredicate = TraceabilityPredicate { blockWorldState ->
        // Module mtes.
        val te = blockWorldState.getTileEntity()
        if (te !is IGregTechTileEntity) return@TraceabilityPredicate false

        val mte: MetaTileEntity? = (te as IGregTechTileEntity).metaTileEntity
        if (mte is ModuleProvider) return@TraceabilityPredicate false
        if (mte !is ModuleReceiver) return@TraceabilityPredicate false

        val moduleReceiver: ModuleReceiver = mte
        if (moduleReceiver.moduleProvider !== this)
        {
            moduleReceiver.moduleProvider = this
            moduleReceivers.add(moduleReceiver)
        }
        true
    }

    @SideOnly(Side.CLIENT)
    override fun getBaseTexture(sourcePart: IMultiblockPart?): ICubeRenderer = GTLiteOverlays.SPACE_ELEVATOR_BASE_CASING

    @SideOnly(Side.CLIENT)
    override fun getFrontOverlay(): ICubeRenderer = GTLiteOverlays.SPACE_ELEVATOR_OVERLAY

    @SideOnly(Side.CLIENT)
    override fun renderMetaTileEntity(renderState: CCRenderState?,
                                      translation: Matrix4?,
                                      pipeline: Array<IVertexOperation?>?)
    {
        super.renderMetaTileEntity(renderState, translation, pipeline)
        this.frontOverlay.renderOrientedState(renderState, translation, pipeline,
                                              getFrontFacing(), true, true)
    }

    override fun hasMaintenanceMechanics() = false

    override fun writeToNBT(data: NBTTagCompound): NBTTagCompound?
    {
        data.setBoolean("isExtended", isExtended)
        return super.writeToNBT(data)
    }

    override fun readFromNBT(data: NBTTagCompound)
    {
        super.readFromNBT(data)
        this.isExtended = data.getBoolean("isExtended")
    }

    override fun writeInitialSyncData(buf: PacketBuffer)
    {
        super.writeInitialSyncData(buf)
        buf.writeBoolean(this.isExtended)
    }

    override fun receiveInitialSyncData(buf: PacketBuffer)
    {
        super.receiveInitialSyncData(buf)
        this.isExtended = buf.readBoolean()
    }

    override fun createUIFactory(): MultiblockUIFactory
    {
        // TODO: replace logo to space elevator logo and add warning/error indicators if necessary.
        return SpaceElevatorUIFactory(this)
            .configureDisplayText(::configureDisplayText)
            .createFlexButton { _, guiSyncManager ->
                guiSyncManager.registerSyncedAction("refresh_structure_pattern") { reinitializeStructurePattern() }
                return@createFlexButton ButtonWidget()
                    .background(GTLiteMuiTextures.BUTTON_REFRESH_STRUCTURE_PATTERN)
                    .disableHoverBackground()
                    .onMousePressed {
                        guiSyncManager.callSyncedAction("refresh_structure_pattern")
                        true
                    }
                    .tooltip { tooltip ->
                        tooltip.addLine(KeyUtil.lang("gtlitecore.machine.space_elevator.refresh_structure_pattern"))
                    }
            }
    }

    override fun configureDisplayText(builder: MultiblockUIBuilder)
    {
        builder.setWorkingStatus(true, isActive)
            .addEnergyUsageLine(energyContainer)
            .addCustom { keyManager, syncer ->
                if (isStructureFormed)
                {
                    val casingTier = syncer.syncInt(::casingTier)
                    val isExtended = syncer.syncBoolean(::isExtended)
                    val maxModules = syncer.syncInt(::maxModules)
                    keyManager.add(
                            KeyUtil.lang(
                                    TextFormatting.GRAY,
                                    "gtlitecore.machine.space_elevator.acceleration_track_tier", casingTier
                            )
                    )
                    keyManager.add(
                            KeyUtil.lang(
                                    TextFormatting.GRAY,
                                    "gtlitecore.machine.space_elevator.max_module_count", maxModules
                            )
                    )
                }

            }
    }

    @SideOnly(Side.CLIENT)
    override fun addInformation(stack: ItemStack, world: World?, tooltip: MutableList<String>, advanced: Boolean)
    {
        super.addInformation(stack, world, tooltip, advanced)
        tooltip.add(I18n.format("gtlitecore.machine.space_elevator.tooltip.1"))
        tooltip.add(I18n.format("gtlitecore.machine.space_elevator.tooltip.2"))
        tooltip.add(I18n.format("gtlitecore.machine.space_elevator.tooltip.3"))
        tooltip.add(I18n.format("gtlitecore.machine.space_elevator.tooltip.4"))
        tooltip.add(I18n.format("gtlitecore.machine.space_elevator.tooltip.5"))
        tooltip.add(I18n.format("gtlitecore.machine.space_elevator.tooltip.6"))
        tooltip.add(I18n.format("gtlitecore.machine.space_elevator.tooltip.7"))
        tooltip.add(I18n.format("gtlitecore.machine.space_elevator.tooltip.8"))
    }

    private enum class ClimberAnimation
    {
        NONE,
        FORMATION,
        DELIVER
    }

    @SideOnly(Side.CLIENT)
    private fun updateClimberAnimation()
    {
        if (!isStructureFormed)
        {
            if (climberFormed)
            {
                climberFormed = false
                resetClimber()
            }
            return
        }

        if (!climberFormed)
        {
            climberFormed = true
            resetClimber()
            startClimberAnimation(ClimberAnimation.FORMATION)
        }

        if (climberAnimation == ClimberAnimation.NONE && ++climberIdleTicks >= CLIMBER_DELIVER_INTERVAL)
            startClimberAnimation(ClimberAnimation.DELIVER)

        previousClimberHeight = climberHeight
        when (climberAnimation)
        {
            ClimberAnimation.FORMATION -> animateClimberFormation()
            ClimberAnimation.DELIVER   -> animateClimberDelivery()
            ClimberAnimation.NONE      -> Unit
        }
    }

    @SideOnly(Side.CLIENT)
    private fun resetClimber()
    {
        climberHeight = CLIMBER_MAX_HEIGHT
        previousClimberHeight = CLIMBER_MAX_HEIGHT
        climberRotation = 0f
        climberWaitTicks = 0
        climberMoving = false
        climberRotating = false
        climberMovingUp = true
        climberIdleTicks = 0
        climberAnimation = ClimberAnimation.NONE
    }

    @SideOnly(Side.CLIENT)
    private fun startClimberAnimation(animation: ClimberAnimation)
    {
        climberAnimation = animation
        climberMoving = true
        climberRotating = true
        climberIdleTicks = 0
    }

    @SideOnly(Side.CLIENT)
    private fun stopClimberAnimation()
    {
        climberAnimation = ClimberAnimation.NONE
        climberMoving = false
        climberRotating = false
    }

    @SideOnly(Side.CLIENT)
    private fun advanceClimberRotation()
    {
        if (!climberRotating) return
        climberRotation = (climberRotation + CLIMBER_ROTATION_SPEED) % 360f
    }

    @SideOnly(Side.CLIENT)
    private fun animateClimberFormation()
    {
        advanceClimberRotation()
        if (!climberMoving) return

        if (climberHeight <= 0f)
        {
            climberMovingUp = true
            stopClimberAnimation()
            return
        }

        climberHeight -= if (climberHeight < CLIMBER_ACCELERATION_DISTANCE)
            CLIMBER_VERTICAL_SPEED * CLIMBER_ACCELERATION_FACTOR * max(climberHeight, 1f)
        else CLIMBER_VERTICAL_SPEED
    }

    @SideOnly(Side.CLIENT)
    private fun animateClimberDelivery()
    {
        advanceClimberRotation()
        if (climberWaitTicks > 0)
        {
            climberWaitTicks--
            return
        }
        if (!climberMoving) return

        if (climberMovingUp)
        {
            when
            {
                climberHeight >= CLIMBER_MAX_HEIGHT ->
                {
                    climberMovingUp = false
                    climberWaitTicks = CLIMBER_STANDBY_TICKS
                }
                climberHeight <= CLIMBER_ACCELERATION_DISTANCE ->
                    climberHeight += climberAcceleration(climberHeight)
                climberHeight >= CLIMBER_MAX_HEIGHT - CLIMBER_ACCELERATION_DISTANCE ->
                    climberHeight += climberAcceleration(CLIMBER_MAX_HEIGHT - climberHeight)
                else -> climberHeight += CLIMBER_VERTICAL_SPEED
            }
        }
        else
        {
            when
            {
                climberHeight <= 0f ->
                {
                    climberMovingUp = true
                    stopClimberAnimation()
                }
                climberHeight < CLIMBER_ACCELERATION_DISTANCE ->
                    climberHeight -= climberAcceleration(climberHeight)
                climberHeight >= CLIMBER_MAX_HEIGHT - CLIMBER_ACCELERATION_DISTANCE ->
                    climberHeight -= climberAcceleration(CLIMBER_MAX_HEIGHT - climberHeight)
                else -> climberHeight -= CLIMBER_VERTICAL_SPEED
            }
        }
    }

    @SideOnly(Side.CLIENT)
    private fun climberAcceleration(remaining: Float): Float
        = CLIMBER_VERTICAL_SPEED * CLIMBER_ACCELERATION_FACTOR * max(remaining, 1f)

    private fun disabledAllModules()
    {
        moduleReceivers.forEach { it.sentWorkingDisabled() }
    }

    private fun enabledAllModules()
    {
        moduleReceivers.forEach { it.sentWorkingEnabled() }
    }

    private fun checkModules() = moduleCount <= maxModules

    private val moduleCount: Int
        get() = moduleReceivers.size

    private val maxModules: Int
        get()
        {
            if (casingTier == 1) return 6
            if (casingTier == 2) return 12
            if (casingTier == 3 && isExtended) return 15
            if (casingTier == 4 && isExtended) return 18
            if (casingTier == 5 && isExtended) return 24
            return 12
        }

    private fun getIsExtended(): Boolean
    {
        return isExtended
    }

    private fun setExtended(extended: Boolean)
    {
        if (isExtended != extended)
        {
            isExtended = extended
            invalidateStructure()
            reinitializeStructurePattern()
        }
    }

    override fun isModule(receiver: ModuleReceiver): Boolean = moduleReceivers.contains(receiver)

    // TODO: Rework it, and new theme for it and all space elevator modules.
    private class SpaceElevatorUIFactory(val controller: MultiblockSpaceElevator) : MultiblockUIFactory(controller)
    {
        override fun createDistinctButton(mainPanel: ModularPanel, panelSyncManager: PanelSyncManager): IWidget
        {
            panelSyncManager.registerSyncedAction("enable_modules") { controller.enabledAllModules() }

            return ButtonWidget()
                .disableHoverBackground()
                .overlay(GTLiteMuiTextures.BUTTON_ENABLE_MODULE)
                .tooltip { tooltip ->
                    tooltip.addLine(KeyUtil.lang("gtlitecore.machine.space_elevator.enable_module"))
                }
                .onMousePressed {
                    panelSyncManager.callSyncedAction("enable_modules")
                    true
                }
        }

        override fun createVoidingButton(mainPanel: ModularPanel, panelSyncManager: PanelSyncManager): IWidget
        {
            panelSyncManager.registerSyncedAction("disable_modules") { controller.disabledAllModules() }

            return ButtonWidget()
                .disableHoverBackground()
                .overlay(GTLiteMuiTextures.BUTTON_DISABLE_MODULE)
                .tooltip { tooltip ->
                    tooltip.addLine(KeyUtil.lang("gtlitecore.machine.space_elevator.disable_module"))
                }.onMousePressed {
                    panelSyncManager.callSyncedAction("disable_modules")
                    true
                }
        }

        override fun createPowerButton(mainPanel: ModularPanel, panelSyncManager: PanelSyncManager): Widget<*>
        {
            val state = BooleanSyncValue(controller::getIsExtended, controller::setExtended)
            return ToggleButton()
                .disableHoverBackground()
                .overlay(false, GTLiteMuiTextures.BUTTON_ELEVATOR_EXTENSION[0])
                .overlay(true, GTLiteMuiTextures.BUTTON_ELEVATOR_EXTENSION[1])
                .addTooltip(false, KeyUtil.lang("gtlitecore.machine.space_elevator.extension_info.disabled"))
                .addTooltip(true, KeyUtil.lang("gtlitecore.machine.space_elevator.extension_info.enabled"))
                .value(state)
        }
    }
}
